package com.bikeshare;

import java.io.*;
import java.util.*;

public class Pin {
    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new FileReader(new File(ListOfWords.DICT_PATH)));
        Set<String> dict = new HashSet<>();
        while (reader.ready()) {
            String line = reader.readLine();
            dict.add(line);
        }

        PrintWriter pw = new PrintWriter(new File("pins.txt"));
        for (String key : dict.keySet()) {
            for (char ch : key.toCharArray()) {
                String syncKey = "0".repeat(key.length());
                for (char m : key.toCharArray()) {
                    for (int i = 0; i < key.length(); i++) {
                        if (m == ch)
                            syncKey = syncKey.substring(0, i) + "1" + syncKey.substring(i + 1);
                        else if(ch == '0' && ch == m)
                            syncKey = syncKey.substring(0, i) + "1" + syncKey.substring(i + 1);
                    }
                }

                pinKey = spawnKey(syncKey);
                if (dict.contains(pinKey)) {
                    pw.printf("%s %s%n", key, pinKey);
                }
            }
        }
    }

    static String pinKey = "";
    static String spawnKey(String str) {
        StringBuilder sb;
        for (char ch : str.toCharArray()) {
            char replacement = 'z' - ch + 'a';
            if(ch == 'a') {
                sb.append("a");
            } else {
                sb.append(replacement);
            }

        }
        return sb.toString();
    }
}


